  patchRaw: <D, T>(url: string, data?: D, config?: any): Promise<AxiosResponse<T>> =>
    axiosInstance.patch<T>(url, data, config),

  deleteRaw: <T>(url: string, config?: any): Promise<AxiosResponse<T>> =>
    axiosInstance.delete<T>(url, config),
};

