      setViewType(mappedViewType as 'weekly' | 'monthly');
    }
  }, [suggestions, selectedSuggestionIndex]);

  const handleConfirm = async () => {
    await onConfirm({
      title,
      body,
      date,
      time: time || undefined,
      view_type: viewType,
    });
    onClose();
  };

  if (loading) {
    return (
      <Dialog 
        open={open} 
        onClose={onClose} 
        title="Analyzing Note"
      >
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', py: 4 }}>
          <CircularProgress />
          <Typography sx={{ mt: 2 }}>Analyzing note with GPT-5...</Typography>
        </Box>
      </Dialog>
    );
  }

  if (!suggestions || suggestions.suggestions.length === 0) {
    return (
      <Dialog 
        open={open} 
        onClose={onClose} 
        title="No Suggestions"
        actions={
          <Button onClick={onClose}>Close</Button>
        }
      >
        <Alert severity="info">
          Unable to generate task suggestions from this note.
        </Alert>
      </Dialog>
    );
  }

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      title="Convert Note to Task"
      actions={
        <>
          <Button onClick={onClose}>Cancel</Button>
          <Button onClick={handleConfirm} variant="contained" disabled={!title || !date}>
            Create Task
          </Button>
        </>
      }
    >
      {suggestions.suggestions.length > 1 && (
        <Box sx={{ mb: 2 }}>
          <Typography variant="caption" color="text.secondary">
            GPT-5 suggested {suggestions.suggestions.length} tasks. Select one:
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
            {suggestions.suggestions.map((_, index) => (
              <Button
                key={index}
                variant={selectedSuggestionIndex === index ? 'contained' : 'outlined'}
                size="small"
                onClick={() => setSelectedSuggestionIndex(index)}
              >
                Suggestion {index + 1}
              </Button>
            ))}
          </Box>
        </Box>
      )}

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
        <TextField
          label="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />

        <TextField
          label="Description"
          multiline
          rows={3}
          value={body}
          onChange={(e) => setBody(e.target.value)}
        />

        <TextField
          label="Date"
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          InputLabelProps={{ shrink: true }}
          required
        />

        <TextField
          label="Time (optional)"
          type="time"
          value={time}
          onChange={(e) => setTime(e.target.value)}
          InputLabelProps={{ shrink: true }}
        />

        <TextField
          label="View Type"
          select
          value={viewType}
          onChange={(e) => setViewType(e.target.value as 'weekly' | 'monthly')}
        >
          <MenuItem value="weekly">Weekly</MenuItem>
          <MenuItem value="monthly">Monthly</MenuItem>
        </TextField>
      </Box>
    </Dialog>
  );
};

